using System;using System.IO;using System.IO.Compression;using System.Drawing;using System.Reflection;using System.Text;using System.Threading;using System.Threading.Tasks;using System.Windows.Forms;
namespace GearLab {public static class PrintExport672Tests {
 static int checks;static void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}static void PumpUntil(Func<bool> ready){var watch=System.Diagnostics.Stopwatch.StartNew();while(!ready()&&watch.Elapsed.TotalSeconds<20){Application.DoEvents();Thread.Sleep(10);}Check(ready(),"operation reached expected state");}static void Get(Task task){PumpUntil(()=>task.IsCompleted);task.GetAwaiter().GetResult();}
 static bool ClosingCancelled(MainForm form){var args=new FormClosingEventArgs(CloseReason.UserClosing,false);typeof(Form).GetMethod("OnFormClosing",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(form,new object[]{args});return args.Cancel;}
 public static int Run(string folder){Directory.CreateDirectory(folder);var old=AppSettings.Current;string oldProfile=Environment.GetEnvironmentVariable("GEARLAB_PROFILE_DIR");try{Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",Path.Combine(Path.GetFullPath(folder),"profile"));AppSettings.Current=new AppSettings{AutoSave=false};var model=new CadAssembly();var part=new CadPart("test","Test printable cylinder","housing",Color.Gray);part.Sections.Add(new CadSection(0,3,CadLoop.Round(0,0,5),null));model.Parts.Add(part);var dialog=new TestDialogs();using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim())using(var form=new MainForm(dialog)){form.Show();var cursor=form.Cursor;string path=Path.Combine(folder,"small.zip");var task=form.ExportPrintZipAsync(model,path,(m,p)=>{entered.Set();if(!release.Wait(15000))throw new TimeoutException("Test writer was not released");PrintExport.Zip(m,p);});try{PumpUntil(()=>entered.IsSet);Check(form.PrintExportInProgress&&!form.StageCanClose,"print marks shared export state busy");Check(!form.WorkspaceCanClose(),"workspace close blocked during print");typeof(MainForm).GetField("dirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,true);Check(ClosingCancelled(form),"window close blocked during print");Check(dialog.UnsavedCalls==0,"busy close never opens an unsaved-changes dialog");typeof(MainForm).GetField("dirty",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(form,false);bool heartbeat=false;form.BeginInvoke(new Action(()=>heartbeat=true));PumpUntil(()=>heartbeat);bool duplicate=false;try{Get(form.ExportPrintZipAsync(model,Path.Combine(folder,"duplicate.zip")));}catch(InvalidOperationException){duplicate=true;}Check(duplicate&&!File.Exists(Path.Combine(folder,"duplicate.zip")),"second export rejected before file creation");}finally{release.Set();}Get(task);Check(!form.PrintExportInProgress&&form.StageCanClose,"success clears all export flags");Check(form.Cursor==cursor,"success restores cursor");Check(!ClosingCancelled(form),"success removes close guard");using(var zip=ZipFile.OpenRead(path))Check(zip.GetEntry("test.stl")!=null,"real print ZIP completed");
 string preserved=Path.Combine(folder,"preserved.zip");File.WriteAllText(preserved,"original");var bad=new CadAssembly();var reference=part.WithPlacement(part.Placement);reference.Reference=true;bad.Parts.Add(reference);bool failed=false;try{Get(form.ExportPrintZipAsync(bad,preserved));}catch(Exception){failed=true;}Check(failed&&File.ReadAllText(preserved)=="original","writer failure preserves original target");Check(!form.PrintExportInProgress&&form.StageCanClose&&form.Cursor==cursor&&!ClosingCancelled(form),"failure rolls back busy state, cursor and close guard");Check(Directory.GetFiles(folder,".gearlab-print-*.tmp").Length==0,"writer failure leaves no partial archive");Get(form.ExportPrintZipAsync(model,Path.Combine(folder,"retry.zip")));Check(File.Exists(Path.Combine(folder,"retry.zip")),"export remains usable after failure");form.WorkspaceApproveClose();form.Close();}File.WriteAllText(Path.Combine(folder,"print-export672-results.txt"),"PASS "+checks+" assertions: real ZIP, responsive UI, reentry/close guards and error rollback.",Encoding.UTF8);return 0;}catch(Exception ex){File.WriteAllText(Path.Combine(folder,"print-export672-error.txt"),ex.ToString(),Encoding.UTF8);return 1;}finally{AppSettings.Current=old;Environment.SetEnvironmentVariable("GEARLAB_PROFILE_DIR",oldProfile);}}
}}
